WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_data_proportion_change'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '比重变化', 'kp-xingce-data-proportion-change', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "比重变化计算"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "不仅定性判断比重升降，还要定量算出差了多少个百分点。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "选项形式一般为：A. 上升了2.1个百分点   B. 下降了2.1个百分点   C. 上升了8.3个百分点。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式"}]}, {"type": "katexBlock", "attrs": {"content": "比重变化 = 现期比重 - 基期比重 = \\frac{A}{B} \\times \\frac{a - b}{1 + a}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤（绝对上限秒杀法）"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[先用 a 和 b 比大小定方向] --> B[排掉两个方向错误的选项]\nB --> C[计算绝对值差 |a - b|]\nC --> D{观察剩下选项的数值}\nD -- 只有一个小于 |a-b| --> E[秒选小于该差值的项!]\nD -- 都小于 |a-b| --> F[估算 现期比重(A/B) × |a-b|]\nF --> G[选择最接近该估算值的选项]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " A/B=20%。a=12%，b=8%。求比重同比变化了多少？选项：A. 上升了0.7个百分点 B. 上升了4.5个百分点 C. 下降了0.7个百分点 D. 下降了4.5个百分点"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "定方向：a(12%) > b(8%)，上升。排除 C, D。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "找上限：上限 |a-b| = 12% - 8% = 4个百分点。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "判选项：真实结果必须小于 4个百分点。选项 A(0.7) 和 B(4.5) 中，只有 A 满足！"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "锁定答案：秒选 A。全过程无需求解复杂算式。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "忘记乘现期比重：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "如果选项里出现了两个都小于 |a-b| 的数据（比如 3.2 和 0.7），必须用 A/B (20%) 去乘 4个百分点，得出大概是 0.8 左右，从而选 0.7。千万别直接猜最大的。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "这题是行测出题人送的福利，90% 的题目都可以用“小于 |a-b|”这一条铁律直接干掉干扰项。切记！"}]}]}$$ AS jsonb), NULL, '比重变化的核心考点与实战推导。', category_node.id, CAST('["资料分析", "比重变化"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_proportion_change", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
